package service

import (
	"fmt"
	"strings"
)

// UserService does too much: data, validation, formatting.
// Refactor: split into UserStore, UserValidator, UserFormatter.
type UserService struct {
	users map[int]string
	nextID int
}

func NewUserService() *UserService {
	return &UserService{users: make(map[int]string), nextID: 1}
}

func (s *UserService) CreateUser(name string) (int, error) {
	if strings.TrimSpace(name) == "" {
		return 0, fmt.Errorf("name cannot be empty")
	}
	id := s.nextID
	s.users[id] = strings.TrimSpace(name)
	s.nextID++
	return id, nil
}

func (s *UserService) GetUser(id int) (string, bool) {
	name, ok := s.users[id]
	return name, ok
}

func (s *UserService) FormatUser(id int) string {
	name, ok := s.users[id]
	if !ok {
		return ""
	}
	return fmt.Sprintf("User#%d: %s", id, strings.ToUpper(name))
}

func (s *UserService) ListUsers() []string {
	result := make([]string, 0, len(s.users))
	for id, name := range s.users {
		result = append(result, fmt.Sprintf("%d:%s", id, name))
	}
	return result
}

