package service_test

import (
	"testing"

	"github.com/ai-verification/refactor-go/service"
)

func TestCreateUser(t *testing.T) {
	svc := service.NewUserService()
	id, err := svc.CreateUser("Alice")
	if err != nil || id == 0 {
		t.Fatalf("expected valid id, got %d %v", id, err)
	}
}

func TestCreateUserEmptyName(t *testing.T) {
	svc := service.NewUserService()
	_, err := svc.CreateUser("")
	if err == nil {
		t.Fatal("expected error for empty name")
	}
}

func TestGetUser(t *testing.T) {
	svc := service.NewUserService()
	id, _ := svc.CreateUser("Bob")
	name, ok := svc.GetUser(id)
	if !ok || name != "Bob" {
		t.Fatalf("expected Bob, got %s %v", name, ok)
	}
}

func TestFormatUser(t *testing.T) {
	svc := service.NewUserService()
	id, _ := svc.CreateUser("alice")
	fmt := svc.FormatUser(id)
	if fmt == "" {
		t.Fatal("expected formatted user")
	}
}

func TestUserStore(t *testing.T) {
	"""Test that UserStore interface exists and works."""
	var _ service.UserStorer = service.NewUserService()
}
